import{_ as n,C as e,o as s,c as d,E as t,a7 as l}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"Vault Nest Privacy Policy","description":"Privacy Policy for Vault Nest, presented within Policy Hub.","frontmatter":{"title":"Vault Nest Privacy Policy","description":"Privacy Policy for Vault Nest, presented within Policy Hub."},"headers":[],"relativePath":"apps/vault-nest/privacy.md","filePath":"apps/vault-nest/privacy.md"}'),c={name:"apps/vault-nest/privacy.md"};function p(u,a,h,m,y,v){const o=e("AppBreadcrumbs"),r=e("AppSubnav"),i=e("CopyStandaloneUrl");return s(),d("div",null,[t(o,{"app-id":"vault-nest",current:"Privacy Policy"}),t(r,{"app-id":"vault-nest"}),t(i,{path:"/privacy/vault-nest",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Vault Nest privacy policy"}),a[0]||(a[0]=l('<h1 id="privacy-policy-for-vault-nest" tabindex="-1">Privacy Policy for Vault Nest <a class="header-anchor" href="#privacy-policy-for-vault-nest" aria-label="Permalink to &quot;Privacy Policy for Vault Nest&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Vault Nest is an offline-first password and sensitive-information manager developed by <strong>Anand Raja</strong>. It has no account service, cloud sync, advertising, analytics, or developer-operated database.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Vault Nest stores the information you enter, which may include login details, passwords, PINs, one-time-password secrets, backup codes, secure notes, identities, Wi-Fi details, labels, websites, custom fields, and saved templates. It also stores app preferences and security settings.</p><p>Sensitive item contents are encrypted with AES-256-GCM in local SQLite storage on Android or IndexedDB in a browser. A random vault key protects the records; your master password derives a separate key used to wrap that vault key. The master password and derived wrapping key are not persisted.</p><p>Some metadata remains outside each encrypted item payload so the app can index records: item identifiers and types, favourite, archive and trash status, expiry dates, and created or updated timestamps. An optional password hint is also visible on the lock screen.</p><p>Encryption reduces risk but cannot guarantee protection if the device, operating system, clipboard, an exported file, or the master password is compromised.</p><h2 id="optional-android-features" tabindex="-1">Optional Android Features <a class="header-anchor" href="#optional-android-features" aria-label="Permalink to &quot;Optional Android Features&quot;">​</a></h2><ul><li><strong>Biometric unlock:</strong> an Android Keystore key protects a wrapped copy of the vault key. Biometric material is processed by Android and is not received by the developer.</li><li><strong>Intrusion evidence:</strong> if you enable this feature and grant camera permission, Vault Nest captures one front-camera image after the third continuous failed unlock attempt. The image is encrypted with an Android-Keystore key and stored in private app storage. It is not included in vault backups. You can review, export, or permanently delete it after unlocking.</li><li><strong>Expiry reminders:</strong> notification permission may be requested for saved credential reminders. Android receives the credential title and expiry date needed to display the notification; secrets and field values are excluded.</li><li><strong>Credential copy shortcuts:</strong> selected usernames, emails, or passwords can be made available through temporary Android notifications. The values are encrypted in private storage for up to three minutes and are not placed in notification text or pending-intent metadata.</li></ul><h2 id="website-icons-and-network-access" tabindex="-1">Website Icons and Network Access <a class="header-anchor" href="#website-icons-and-network-access" aria-label="Permalink to &quot;Website Icons and Network Access&quot;">​</a></h2><p>The core vault works without an internet connection. On Android, Vault Nest may request artwork for a website address saved in a vault item. This connects to the entered website and possible image locations to retrieve an icon. Those servers can receive ordinary connection data such as the device IP address, request time, requested URL, and a Vault Nest browser user agent. Their own privacy terms apply. The downloaded image is stored as part of the encrypted vault item.</p><p>Vault Nest does not send passwords or other vault fields to those websites.</p><h2 id="clipboard-and-sharing" tabindex="-1">Clipboard and Sharing <a class="header-anchor" href="#clipboard-and-sharing" aria-label="Permalink to &quot;Clipboard and Sharing&quot;">​</a></h2><p>Copying a field places its value on the system clipboard, outside Vault Nest&#39;s encrypted storage. The app attempts to clear copied values after five minutes, but this is best effort because Android may stop the app. You can clear the clipboard immediately from Settings.</p><p>When you use system sharing, only the fields you select are passed to Android and the destination app. Sensitive fields are excluded by default and require explicit selection. The destination app&#39;s privacy practices then apply.</p><h2 id="backup-restore-and-export" tabindex="-1">Backup, Restore, and Export <a class="header-anchor" href="#backup-restore-and-export" aria-label="Permalink to &quot;Backup, Restore, and Export&quot;">​</a></h2><p>Vault Nest <code>.vaultpack</code> backups are encrypted with AES-256-GCM using a key derived from a separate backup passphrase. The passphrase is not stored. You choose the file destination through Android&#39;s document picker or the browser. If you select a cloud-storage provider, that provider receives the encrypted file under its own privacy terms.</p><p>CSV export is intentionally unencrypted for compatibility with other password managers. It can contain readable passwords and other sensitive vault data. Anyone with access to the exported CSV can read it. Protect it and delete it after use.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information Collected by the Developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information Collected by the Developer&quot;">​</a></h2><p>The developer does not receive vault contents, encryption keys, master passwords, app preferences, evidence images, or usage telemetry. Vault Nest does not sell user information.</p><p>If you contact the developer by email, the information you include is used to respond to the request. Do not send passwords, master passwords, backup files, CSV exports, or other secrets.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Depending on the features you choose and Android version, Vault Nest may use:</p><ul><li>Camera permission for optional intrusion evidence</li><li>Notification permission for optional reminders and copy shortcuts</li><li>Biometric authentication for optional biometric unlock</li><li>Internet access for optional website-icon retrieval</li><li>System document-picker access only to files you choose for import or export</li></ul><p>Vault Nest does not require broad storage, location, contacts, phone, or SMS permission for the reviewed features.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Vault data remains locally until you delete items, clear the vault database, remove the Vault Nest account, clear Android app storage, or uninstall the app. Items moved to Trash follow the selected retention period: 7, 30, or 90 days, or remain until manually deleted when <strong>Never</strong> is selected.</p><p>Removing the account deletes the local database, preferences, biometric material, temporary notification values, and encrypted intrusion evidence. Exported backups and CSV files remain wherever you saved or shared them and must be deleted separately.</p><p>There is no developer-operated account or cloud vault to delete by email.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Vault Nest is not designed to collect information from children and does not knowingly collect children&#39;s personal information through a developer-operated service.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Vault Nest&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',37))])}const g=n(c,[["render",p]]);export{b as __pageData,g as default};
